$ErrorActionPreference = 'Stop'
Write-Host "PAGESPEED 99->100 FIX + Unlimited SEO + Logo Optimized" -ForegroundColor Cyan

if (Test-Path "src\app\sitemap.ts") { Remove-Item "src\app\sitemap.ts" -Force }
if (Test-Path "src\app\robots.ts") { Remove-Item "src\app\robots.ts" -Force }
if (Test-Path "public\sitemap.xml") { Remove-Item "public\sitemap.xml" -Force }
if (Test-Path "public\robots.txt") { Remove-Item "public\robots.txt" -Force }

New-Item -ItemType Directory -Force -Path "public" | Out-Null
New-Item -ItemType Directory -Force -Path "src\lib" | Out-Null
New-Item -ItemType Directory -Force -Path "src\components" | Out-Null
New-Item -ItemType Directory -Force -Path "src\app" | Out-Null
New-Item -ItemType Directory -Force -Path "src\app\sitemap.xml" | Out-Null
New-Item -ItemType Directory -Force -Path "src\app\robots.txt" | Out-Null

$utf8NoBom = New-Object System.Text.UTF8Encoding $false

Write-Host "1. Fixing logo - 1600x1600 -> 512x512 optimized" -ForegroundColor Yellow
$logoB64 = @"

"@
$logoBytes = [System.Convert]::FromBase64String($logoB64)
[System.IO.File]::WriteAllBytes("public\logo.png", $logoBytes)
Copy-Item "public\logo.png" "public\favicon.ico" -Force -ErrorAction SilentlyContinue

$logo32B64 = @"

"@
[System.IO.File]::WriteAllBytes("public\logo-32.png", [System.Convert]::FromBase64String($logo32B64))

$logo192B64 = @"

"@
[System.IO.File]::WriteAllBytes("public\logo-192.png", [System.Convert]::FromBase64String($logo192B64))

Write-Host "2. Manifest" -ForegroundColor Yellow
$mB64 = @"

"@
[System.IO.File]::WriteAllText("public\manifest.webmanifest", [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($mB64)), $utf8NoBom)

Write-Host "3. Brand SEO Unlimited" -ForegroundColor Yellow
$b64 = @"

"@
[System.IO.File]::WriteAllText("src\lib\brand.ts", [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($b64)), $utf8NoBom)

Write-Host "4. Header optimized" -ForegroundColor Yellow
$b64 = @"

"@
[System.IO.File]::WriteAllText("src\components\BrandHeader.tsx", [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($b64)), $utf8NoBom)

Write-Host "5. Layout optimized - Preconnect + display swap" -ForegroundColor Yellow
$b64 = @"

"@
[System.IO.File]::WriteAllText("src\app\layout.tsx", [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($b64)), $utf8NoBom)

Write-Host "6. next.config.js - AVIF/WebP, Cache, Compress" -ForegroundColor Yellow
$b64 = @"

"@
[System.IO.File]::WriteAllText("next.config.js", [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($b64)), $utf8NoBom)

$b64 = @"

"@
[System.IO.File]::WriteAllText("src\app\sitemap.xml\route.ts", [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($b64)), $utf8NoBom)

$b64 = @"

"@
[System.IO.File]::WriteAllText("src\app\robots.txt\route.ts", [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($b64)), $utf8NoBom)

Write-Host "DONE! Performance fixes applied, Content NOT touched!" -ForegroundColor Green
npm run build
